-- HSR: per-character farming attributes (trace-mat family, boss mat, weekly mat, cost profile, extra-talent maxima) for the TP planner.
-- Run once after 0007 (safe to re-run). Adds the per-path Trailblazer rows the master list is missing. Source: the TP Planner sheet, Oct 2026.
create temp table _hfarm(name text, rarity int, element text, path text, farm jsonb, released boolean);
-- characters missing from the master list are added (the per-path Trailblazers as free units)
select 'hsr', h.name, h.rarity, h.element, h.path, false, h.name like 'Trailblazer%', h.released, 'tp-planner', h.farm
from _hfarm h where not exists (select 1 from public.characters c where c.game_id='hsr' and lower(c.name)=lower(h.name));
update public.characters c set farm = h.farm, element = coalesce(c.element, h.element), weapon_type = coalesce(c.weapon_type, h.path)
from _hfarm h where c.game_id='hsr' and lower(c.name)=lower(h.name);
-- Aha's new materials can't be farmed before 4.7 (expected ~10 Nov 2026); the planner locks them until the release date
update public.characters set release_date = coalesce(release_date, '2026-11-10') where game_id='hsr' and name = 'Aeon ★ Aha' and not is_released;
select (select count(*) from public.characters where game_id='hsr' and farm <> '{}'::jsonb) as with_farm,
       (select string_agg(name, ', ') from public.characters where game_id='hsr' and (farm is null or farm = '{}'::jsonb)) as names_without;
drop table _hfarm;
